#!/usr/bin/env python3
"""audio/tempomap.json -> src/tempo.js (window.TEMPO_BEATS: beat n -> seconds, 4 decimals). See tempomap.py."""
import json
import sys

src = sys.argv[1] if len(sys.argv) > 1 else 'audio/tempomap.json'
out = sys.argv[2] if len(sys.argv) > 2 else 'src/tempo.js'
beats = json.load(open(src))['beats']
with open(out, 'w') as fh:
    fh.write('// tempo.js - measured beat times (drum onsets of the no-vocals stem). beat n -> seconds.\n'
             '// Generated by tools/audio/make_tempo_js.py from audio/tempomap.json (see tools/audio/tempomap.py).\n')
    fh.write('window.TEMPO_BEATS=' + json.dumps([round(b, 4) for b in beats]) + ';\n')
print(len(beats), 'beats ->', out)
